/* eslint-env serviceworker */
/* global self, caches, fetch */

/**
 * ProcureFlow Scanner service worker.
 *
 * Hand-written rather than generated by Workbox. Workbox's Next.js integrations
 * (next-pwa, @serwist/next) wrap the build and pin themselves to particular
 * Next versions, which is a large, brittle dependency to take on for what this
 * app actually needs: an app shell that survives a dead signal, and static
 * assets served from cache. The caching rules below are the whole requirement,
 * and they are more legible written out than configured.
 *
 * The deliberate omission is the API. Nothing under /api is ever cached:
 * stock figures, pick progress and count variances are exactly the data that
 * must not be shown stale to someone standing at a shelf deciding what to move.
 * Offline writes are not the service worker's job either — they belong to the
 * IndexedDB queue, which survives the app being closed entirely.
 */

const VERSION = 'scan-v1';
const SHELL_CACHE = `${VERSION}-shell`;
const ASSET_CACHE = `${VERSION}-assets`;

/** Enough to boot the scanner with no network at all. */
const SHELL_URLS = ['/scan', '/scan/offline', '/manifest.webmanifest', '/icons/scanner-192.png'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Individually, not addAll: one 404 during a deploy must not leave the
      // worker uninstalled and the whole app without an offline shell.
      await Promise.all(
        SHELL_URLS.map(async (url) => {
          try {
            await cache.add(new Request(url, { cache: 'reload' }));
          } catch {
            /* precache miss — runtime caching will pick it up */
          }
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => !n.startsWith(VERSION)).map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') void self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // The API is never cached — see the note at the top of this file.
  if (url.pathname.startsWith('/api/')) return;

  // Immutable build output: cache-first, since the filename changes on rebuild.
  if (url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/icons/')) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  // Page navigations: network-first so a connected operator always gets the
  // current build, with the cached shell as the fallback when the signal drops.
  if (request.mode === 'navigate') {
    event.respondWith(navigationFallback(request));
    return;
  }

  if (url.pathname.startsWith('/scan')) {
    event.respondWith(staleWhileRevalidate(request, ASSET_CACHE));
  }
});

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;

  const response = await fetch(request);
  if (response.ok) void cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) void cache.put(request, response.clone());
      return response;
    })
    .catch(() => hit);
  return hit ?? network;
}

async function navigationFallback(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(SHELL_CACHE);
      void cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cache = await caches.open(SHELL_CACHE);
    return (
      (await cache.match(request)) ??
      (await cache.match('/scan')) ??
      (await cache.match('/scan/offline')) ??
      new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } })
    );
  }
}
